import {fresh,get,outputSize} from './engine.mjs';
const vertex=`attribute vec2 aPosition;varying vec2 uv;void main(){uv=vec2((aPosition.x+1.)*.5,1.-(aPosition.y+1.)*.5);gl_Position=vec4(aPosition,0.,1.);}`;
const fragment=`precision highp float;varying vec2 uv;uniform sampler2D photo,lut,matte,background,localMask;uniform vec4 crop;uniform vec2 texel,pivot,bgScale;uniform vec3 motion,bgColor;uniform vec4 local;uniform float turns,flipX,flipY,cutout,portrait,edge,bgMode,grain,vignette,sharp;
vec3 grade(vec3 x){vec3 c=clamp(x,0.,1.);float b=c.b*15.,lo=floor(b),hi=min(15.,lo+1.);vec2 a=vec2((lo*16.+c.r*15.+.5)/256.,(c.g*15.+.5)/16.);vec2 d=vec2((hi*16.+c.r*15.+.5)/256.,(c.g*15.+.5)/16.);return mix(texture2D(lut,a).rgb,texture2D(lut,d).rgb,b-lo);}
float weight(vec2 p){if(p.x<0.||p.y<0.||p.x>1.||p.y>1.)return 0.;return smoothstep(clamp(.08+edge/400.,0.,.8),clamp(.85+edge/400.,.2,1.),texture2D(matte,p).r);}
vec4 samplePhoto(vec2 p){if(p.x<0.||p.y<0.||p.x>1.||p.y>1.)return vec4(0.);vec4 raw=texture2D(photo,p);vec3 c=grade(raw.rgb);if(abs(sharp)>.001){vec3 blur=vec3(0.);for(int j=-1;j<=1;j++)for(int i=-1;i<=1;i++)blur+=grade(texture2D(photo,p+vec2(float(i),float(j))*texel).rgb)/9.;c=clamp(c+sharp*(c-blur),0.,1.);}float m=texture2D(localMask,p).r*local.w;if(m>0.){vec3 adjusted=clamp((c*pow(2.,local.x)-.5)*(1.+local.y/200.)+.5,0.,1.);float l=dot(adjusted,vec3(.2126,.7152,.0722));adjusted=clamp(vec3(l)+(adjusted-vec3(l))*(1.+local.z/100.),0.,1.);c=mix(c,adjusted,m);}if(vignette!=0.){float d=length((p-.5)*2.);c*=1.+vignette/120.*smoothstep(.42,1.14,d);}if(grain>0.){float n=fract(sin(dot(floor(p/texel),vec2(12.9898,78.233)))*43758.5453)-.5;c+=n*grain/650.;}return vec4(clamp(c,0.,1.),raw.a);}
void main(){vec2 q=uv;if(turns>.5&&turns<1.5)q=vec2(uv.y,1.-uv.x);else if(turns>1.5&&turns<2.5)q=1.-uv;else if(turns>2.5)q=vec2(1.-uv.y,uv.x);if(flipX>.5)q.x=1.-q.x;if(flipY>.5)q.y=1.-q.y;vec2 p=crop.xy+q*crop.zw;vec4 color;
if(cutout>.5){vec2 fg=pivot+(p-pivot-motion.xy)/max(.1,motion.z);vec4 a=samplePhoto(fg);a.a*=weight(fg);vec4 bg=vec4(0.);if(bgMode>.5&&bgMode<1.5)bg=vec4(bgColor,1.);else if(bgMode>1.5)bg=texture2D(background,(p-.5)*bgScale+.5);float alpha=a.a+bg.a*(1.-a.a);color=vec4((a.rgb*a.a+bg.rgb*bg.a*(1.-a.a))/max(.00001,alpha),alpha);}
else{color=samplePhoto(p);if(portrait>0.){vec3 blurred=vec3(0.);float sum=0.;for(int j=-2;j<=2;j++)for(int i=-2;i<=2;i++){vec2 at=clamp(p+vec2(float(i),float(j))*portrait*.00018,0.,1.);float w=(1.-weight(at))*exp(-float(i*i+j*j)/3.);blurred+=grade(texture2D(photo,at).rgb)*w;sum+=w;}if(sum>.0001)color.rgb=mix(blurred/sum,color.rgb,weight(p));}}
gl_FragColor=color;}`;
export class Renderer{
 constructor(canvas){this.canvas=canvas;this.gl=canvas.getContext('webgl',{alpha:true,premultipliedAlpha:false,antialias:false,preserveDrawingBuffer:true,powerPreference:'high-performance'});if(!this.gl)throw Error('متصفحك لا يدعم محرك المعاينة. افتح Safari محدّثًا.');let g=this.gl;const compile=(type,text)=>{let s=g.createShader(type);g.shaderSource(s,text);g.compileShader(s);if(!g.getShaderParameter(s,g.COMPILE_STATUS))throw Error(g.getShaderInfoLog(s));return s};this.program=g.createProgram();g.attachShader(this.program,compile(g.VERTEX_SHADER,vertex));g.attachShader(this.program,compile(g.FRAGMENT_SHADER,fragment));g.linkProgram(this.program);if(!g.getProgramParameter(this.program,g.LINK_STATUS))throw Error(g.getProgramInfoLog(this.program));g.useProgram(this.program);let buffer=g.createBuffer();g.bindBuffer(g.ARRAY_BUFFER,buffer);g.bufferData(g.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),g.STATIC_DRAW);let pos=g.getAttribLocation(this.program,'aPosition');g.enableVertexAttribArray(pos);g.vertexAttribPointer(pos,2,g.FLOAT,false,0,0);this.uniforms={};for(let key of ['crop','texel','pivot','bgScale','motion','bgColor','local','turns','flipX','flipY','cutout','portrait','edge','bgMode','grain','vignette','sharp'])this.uniforms[key]=g.getUniformLocation(this.program,key);this.textures={};['photo','lut','matte','background','localMask'].forEach((k,i)=>{g.activeTexture(g.TEXTURE0+i);let t=g.createTexture();g.bindTexture(g.TEXTURE_2D,t);g.texParameteri(g.TEXTURE_2D,g.TEXTURE_WRAP_S,g.CLAMP_TO_EDGE);g.texParameteri(g.TEXTURE_2D,g.TEXTURE_WRAP_T,g.CLAMP_TO_EDGE);g.texParameteri(g.TEXTURE_2D,g.TEXTURE_MIN_FILTER,g.LINEAR);g.texParameteri(g.TEXTURE_2D,g.TEXTURE_MAG_FILTER,g.LINEAR);g.texImage2D(g.TEXTURE_2D,0,g.RGBA,1,1,0,g.RGBA,g.UNSIGNED_BYTE,new Uint8Array(k==='matte'?[255,255,255,255]:[0,0,0,255]));g.uniform1i(g.getUniformLocation(this.program,k),i);this.textures[k]={t,unit:i}});this.source=null;this.sourceW=1;this.sourceH=1;this.bgW=1;this.bgH=1;this.bounds=[.15,.1,.7,.8];this.maxTexture=g.getParameter(g.MAX_TEXTURE_SIZE);}
 upload(key,data,w,h){let g=this.gl,{t,unit}=this.textures[key];g.activeTexture(g.TEXTURE0+unit);g.bindTexture(g.TEXTURE_2D,t);g.pixelStorei(g.UNPACK_PREMULTIPLY_ALPHA_WEBGL,false);g.pixelStorei(g.UNPACK_FLIP_Y_WEBGL,false);if(w)g.texImage2D(g.TEXTURE_2D,0,g.RGBA,w,h,0,g.RGBA,g.UNSIGNED_BYTE,data);else g.texImage2D(g.TEXTURE_2D,0,g.RGBA,g.RGBA,g.UNSIGNED_BYTE,data);}
 setSource(source){this.source=source;this.sourceW=source.videoWidth||source.naturalWidth||source.width;this.sourceH=source.videoHeight||source.naturalHeight||source.height;if(Math.max(this.sourceW,this.sourceH)>this.maxTexture)throw Error('هذا الملف أكبر من ذاكرة المعاينة. اختر نسخة أصغر.');this.upload('photo',source);}
 setLut(bytes){this.upload('lut',bytes,256,16);}
 setMatte(alpha,bounds){const n=Math.sqrt(alpha.length),rgba=new Uint8Array(alpha.length*4);for(let i=0;i<alpha.length;i++){rgba[i*4]=rgba[i*4+1]=rgba[i*4+2]=alpha[i];rgba[i*4+3]=255}this.upload('matte',rgba,n,n);if(bounds)this.bounds=bounds;}
 setBackground(source){if(source){this.bgW=source.naturalWidth||source.width;this.bgH=source.naturalHeight||source.height;this.upload('background',source);}}
 setLocalMask(canvas){this.upload('localMask',canvas);}
 render(recipe=fresh(),{side=1400,maxPixels=12000000,cropMode=false,before=false,videoFrame=false}={}){if(!this.source)return;let g=this.gl,p=before?fresh():recipe;let dims=outputSize(this.sourceW,this.sourceH,cropMode?{...p,crop:[0,0,1,1],turns:0}:p,side,maxPixels);if(this.canvas.width!==dims[0]||this.canvas.height!==dims[1]){this.canvas.width=dims[0];this.canvas.height=dims[1]}g.viewport(0,0,...dims);g.useProgram(this.program);if(videoFrame)this.upload('photo',this.source);for(let {t,unit}of Object.values(this.textures)){g.activeTexture(g.TEXTURE0+unit);g.bindTexture(g.TEXTURE_2D,t)}let u=this.uniforms;g.uniform4fv(u.crop,cropMode?[0,0,1,1]:p.crop);g.uniform2f(u.texel,1/this.sourceW,1/this.sourceH);g.uniform2f(u.pivot,this.bounds[0]+this.bounds[2]/2,this.bounds[1]+this.bounds[3]/2);g.uniform3f(u.motion,p.subjectX,p.subjectY,p.subjectScale);let a=this.sourceW/this.sourceH,b=this.bgW/this.bgH;g.uniform2f(u.bgScale,a<b?a/b:1,a>b?b/a:1);g.uniform3fv(u.bgColor,p.background.color??[1,1,1]);let m=p.masks?.[0];g.uniform4f(u.local,m?.exposure??0,m?.contrast??0,m?.saturation??0,m?1:0);for(let [k,v]of Object.entries({turns:cropMode?0:p.turns,flipX:!cropMode&&p.flipX?1:0,flipY:!cropMode&&p.flipY?1:0,cutout:p.cutout?1:0,portrait:p.portrait,edge:p.edge,bgMode:p.background.type==='solid'?1:p.background.type==='image'?2:0,grain:get(p,'grain'),vignette:get(p,'vignette'),sharp:get(p,'sharpen')/80+get(p,'texture')/180})){g.uniform1f(u[k],v)}g.drawArrays(g.TRIANGLE_STRIP,0,4);}
 destroy(){this.gl.getExtension('WEBGL_lose_context')?.loseContext();}
}
